    32	#include "idn2.h"
    33	#include "fuzzer.h"
    34	
    35	#pragma GCC optimize ("O0")
    36	
    37	int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
    38	{
    39	        char *domain;
    40	        char *out;
    41	        const char *x = "";
    42	
    43	        if (size > 1024)
    44	                return 0;
    45	
    46	        domain = (char *) malloc(size + 1);
    47	        assert(domain != NULL);
    48	
    49	        // 0 terminate
    50	        memcpy(domain, data, size);
    51	        domain[size] = 0;
    52	
    53	        if (size == 0) {
    54	                x = idn2_check_version(NULL);
    55	
    56	                for (int err = -500; err <= 0; err++) {
    57	                        if (idn2_strerror_name(err))
    58	                                x = NULL;
    59	                        if (idn2_strerror(err))
    60	                                x = NULL;
    61	                }
    62	
    63	                /*** test NULL input/output combinations ***/
    64	
    65	                if (idn2_to_unicode_lzlz(NULL, &out, 0) == IDN2_OK)
    66	                        idn2_free(out);
    67	                idn2_to_unicode_lzlz(NULL, NULL, 0);
    68	                idn2_to_unicode_lzlz(domain, NULL, 0);
    69	
    70	                {
    71	                        uint32_t *in32 = (uint32_t *) malloc(4);
    72	                        uint32_t *out32;
    73	                        in32[0] = 0;
    74	                        if (idn2_to_unicode_4z4z(NULL, &out32, 0) == IDN2_OK)
    75	                                idn2_free(out32);
    76	                        idn2_to_unicode_4z4z(NULL, NULL, 0);
    77	                        idn2_to_unicode_4z4z(in32, NULL, 0);
    78	                        free(in32);
    79	                }
    80	
    81	                {
    82	                        uint32_t *out32;
    83	                        if (idn2_to_unicode_8z4z(NULL, &out32, 0) == IDN2_OK)
    84	                                idn2_free(out32);
    85	                        idn2_to_unicode_8z4z(NULL, NULL, 0);
    86	                        idn2_to_unicode_8z4z(domain, NULL, 0);
    87	                }
    88	
    89	                {
    90	                        uint32_t *u32 = (uint32_t *) malloc(0);
    91	                        size_t u32len = 0;
    92	                        idn2_to_unicode_44i(NULL, 1, u32, &u32len, 0);
    93	                        u32len = 0;
    94	                        idn2_to_unicode_44i(NULL, 0, NULL, &u32len, 0);
    95	                        free(u32);
    96	                }
    97	        }
    98	
    99	        // let's fuzz gnulib's strverscmp()
   100	        if (idn2_check_version(domain))
   101	                x = NULL;
   102	
   103	        if (x)
   104	                free(malloc(1)); // prevent compiler from optimizing out idn2_check_version()
   105	
   106	        // internally calls idn2_to_unicode_8zlz(), idn2_to_unicode_8z8z(), idn2_to_unicode_8z4z()
   107	        if (idn2_to_unicode_lzlz(domain, &out, 0) == IDN2_OK)
   108	                idn2_free(out);
   109	
   110	        if ((size & 3) == 0) {
   111	                uint32_t *u32 = (uint32_t *) malloc(size);
   112	                size_t u32len;
   113	
   114	                assert(u32 != NULL);
   115	
   116	                // internally calls idn2_to_unicode_4z4z(), idn2_to_unicode_8z4z()
   117	                u32len = size / 4;
   118	                idn2_to_unicode_44i((uint32_t *) data, size / 4, u32, &u32len, 0);
   119	
   120	                free(u32);
   121	        }
   122	
   123	        free(domain);
   124	        return 0;
   125	}
